        public static IReadOnlyDictionary<string, string> LegacyToBsg => OldIdToBsgId;

        public static string ResolveBsgId(string idOrUrl)
        {
            if (string.IsNullOrEmpty(idOrUrl)) return idOrUrl;
            if (OldIdToBsgId.TryGetValue(idOrUrl, out var bsgId)) return bsgId;
            return idOrUrl;
        }
